module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);

wire [7:0] sum_low;
wire [7:0] sum_high;
wire carry_low;
wire carry_high;

// Instantiate 8-bit adder modules
assign {carry_low, sum_low} = a[7:0] + b[7:0] + Cin;
assign {carry_high, sum_high} = a[15:8] + b[15:8] + carry_low;

// Combine the results
assign y = {sum_high, sum_low};
assign Co = carry_high;

endmodule
